-- Replace observation identity with the fee semantics actually consumed by IN snapshot kernels.
-- No source rows, artifacts, jobs, heads, schedules or privileges are changed/rebound.
begin;
set local statement_timeout='3s';
set local lock_timeout='500ms';
do $install$
declare actual jsonb;begin
 if current_user<>'postgres'then raise exception using errcode='42501',message='snapshot_fee_dependency_installer_denied';end if;
 if not pg_try_advisory_xact_lock(hashtextextended('provider_snapshot_shadow_worker_v1',0))
  or not pg_try_advisory_xact_lock(hashtextextended('provider_snapshot_dispatch_v1',0))then
  raise exception using errcode='55000',message='snapshot_fee_dependency_busy';end if;
 if exists(select 1 from private.provider_snapshot_jobs where status='running'and lease_until>clock_timestamp())then
  raise exception using errcode='55000',message='snapshot_fee_dependency_active_lease';end if;
 lock table private.fee_rate_versions,private.fee_rate_current_evidence,private.fee_rate_generations,public.third_party_rates in access share mode nowait;
 select jsonb_agg(to_jsonb(q)order by name)into actual from(select n.nspname||'.'||c.relname name,c.relkind kind,pg_get_userbyid(c.relowner)owner,c.relrowsecurity rls,c.relforcerowsecurity force_rls,
