entity":"","generated":""},{"name":"payout_fee","type":"text","notNull":true,"ordinal":7,"identity":"","generated":""},{"name":"total_fee","type":"text","notNull":true,"ordinal":8,"identity":"","generated":""},{"name":"collect_single_fee","type":"text","notNull":true,"ordinal":9,"identity":"","generated":""},{"name":"payout_single_fee","type":"text","notNull":true,"ordinal":10,"identity":"","generated":""},{"name":"collect_limit","type":"text","notNull":true,"ordinal":11,"identity":"","generated":""},{"name":"payout_limit","type":"text","notNull":true,"ordinal":12,"identity":"","generated":""},{"name":"channel_info","type":"text","notNull":true,"ordinal":13,"identity":"","generated":""},{"name":"leak","type":"text","notNull":true,"ordinal":14,"identity":"","generated":""},{"name":"whitelist","type":"text","notNull":true,"ordinal":15,"identity":"","generated":""},{"name":"status","type":"text","notNull":true,"ordinal":16,"identity":"","generated":""},{"name":"source_row","type":"integer","notNull":true,"ordinal":17,"identity":"","generated":""},{"name":"created_at","type":"timestamp with time zone","notNull":true,"ordinal":18,"identity":"","generated":""},{"name":"updated_at","type":"timestamp with time zone","notNull":true,"ordinal":19,"identity":"","generated":""}]}]$tables$::jsonb then raise exception using errcode='55000',message='snapshot_fee_dependency_table_drift';end if;
