ariadic":0,"prokind":"f","proretset":false,"argtypes":"25 25","allargtypes":null,"argmodes":null,"argnames":"{p_country,p_platform}","arguments":"p_country text, p_platform text DEFAULT ''::text","result":"text"},{"signature":"private.provider_snapshot_dependency_token(jsonb)","body_md5":"ccf807a978ba7f0d3cb9f527dad6c5d4","language":"sql","owner":"postgres","prosecdef":false,"provolatile":"s","proparallel":"u","proisstrict":false,"proleakproof":false,"proconfig":["search_path=\"\""],"acl":"{postgres=X/postgres}","procost":100,"prorows":0,"pronargs":1,"pronargdefaults":0,"variadic":0,"prokind":"f","proretset":false,"argtypes":"3802","allargtypes":null,"argmodes":null,"argnames":"{p_target}","arguments":"p_target jsonb","result":"text"}]$after$::jsonb then raise exception using errcode='55000',message='snapshot_fee_dependency_after_drift';end if;
end;$install$;
